\ir _helpers/auth_session.sql
begin;
insert into public.professional_listing_limits(kind,max_per_owner)values('professional',10),('space',10) on conflict(kind)do update set max_per_owner=10;

select no_plan();
-- Isolate public projections from unrelated local preview fixtures, without deleting them.
update private.commercial_resources set moderation_state='draft' where offering_code in('professional_profile','establishment_profile');
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select ('75000000-0000-0000-0000-'||lpad(i::text,12,'0'))::uuid,'authenticated','authenticated','phase5-'||i||'@example.invalid','x',now(),'{}','{}',now(),now() from generate_series(1,4)i;
update public.users set usage_profile=case when id='75000000-0000-0000-0000-000000000002' then 'establishment_owner' else 'professional' end where id::text like '75000000-%';
update public.users set role='superadmin' where id='75000000-0000-0000-0000-000000000004';
create function pg_temp.pro_user(n integer) returns void language sql as $$select pg_temp.set_test_user(('75000000-0000-0000-0000-'||lpad(n::text,12,'0')),true)$$;
create function pg_temp.pro_admin() returns void language plpgsql as $$begin
 perform pg_temp.pro_user(4);perform set_config('request.jwt.claims',(current_setting('request.jwt.claims')::jsonb||jsonb_build_object('amr',jsonb_build_array(jsonb_build_object('method','password','timestamp',extract(epoch from clock_timestamp())::bigint))))::text,true);
end$$;
create temp table pro_ids(k text primary key,v uuid);grant all on pro_ids to authenticated;grant select on pro_ids to anon;
create function pg_temp.pro_rev(k text) returns bigint language sql security definer set search_path='' as $$select d.version::bigint from public.professional_listing_drafts d where listing_id=(select v from pro_ids where pro_ids.k=$1)$$;
create function pg_temp.pro_data(kind text,name text,mid uuid default null) returns jsonb language sql as $$select jsonb_build_object('kind',kind,'displayName',name,'categoryKey',case when kind='space' then 'academia' else 'personal_trainer' end,'modalityKeys',jsonb_build_array('musculacao'),'specialties',jsonb_build_array('Treino de força'),'bio','Descrição sintética completa de apresentação.','city','São Paulo','uf','SP','serviceMode','in_person','contacts',jsonb_build_object('website','https://example.invalid/contact'),'mediaId',mid,'address',case when kind='space' then 'Rua de Teste, 100' else '' end,'openingHours',case when kind='space' then 'Segunda a sexta, 8h às 18h' else '' end)$$;
select pg_temp.pro_admin();
select public.admin_publish_commercial_price('professional_profile','5',1,30,null,(select revision from public.commercial_offerings where code='professional_profile'),gen_random_uuid(),'Synthetic Phase 5 fixture only',true);
select public.admin_publish_commercial_price('establishment_profile','8',1,30,null,(select revision from public.commercial_offerings where code='establishment_profile'),gen_random_uuid(),'Synthetic Phase 5 fixture only',true);
select public.admin_set_commercial_sales('professional_profile',true,(select revision from public.commercial_offerings where code='professional_profile'),gen_random_uuid(),'Synthetic Phase 5 fixture only',true);
select public.admin_set_commercial_sales('establishment_profile',true,(select revision from public.commercial_offerings where code='establishment_profile'),gen_random_uuid(),'Synthetic Phase 5 fixture only',true);
select public._wallet_credit_cash('75000000-0000-0000-0000-000000000001',100);
select public._ledger_record('75000000-0000-0000-0000-000000000001','phase5-fixture-pro','cash','credit',100,'synthetic','fixture','phase5');
select public._wallet_credit_cash('75000000-0000-0000-0000-000000000002',100);
select public._ledger_record('75000000-0000-0000-0000-000000000002','phase5-fixture-space','cash','credit',100,'synthetic','fixture','phase5');
delete from public.professional_listing_limits;
select pg_temp.pro_user(1);set local role authenticated;
select throws_ok($$select public.create_professional_listing('professional',gen_random_uuid())$$,'LISTING_LIMIT_UNCONFIGURED','missing policy blocks creation without inventing a default');
select throws_ok($$select public.create_professional_listing('professional')$$,'LISTING_CREATION_KEY_REQUIRED','stale creation API cannot choose a resource implicitly');
select throws_ok($$select public.get_my_professional_listing()$$,'LISTING_ID_REQUIRED','stale getter cannot choose an arbitrary resource');
select throws_ok($$select public.admin_set_professional_listing_limit('space',3,0,'Attempt unauthorized config')$$,'42501','PERMISSION_DENIED','owner cannot configure its own limit');
reset role;select pg_temp.pro_admin();set local role authenticated;
select public.admin_set_professional_listing_limit('professional',2,0,'Synthetic multiple-resource fixture');
select public.admin_set_professional_listing_limit('space',2,0,'Synthetic multiple-resource fixture');
select throws_ok($$select public.admin_set_professional_listing_limit('space',9,0,'Stale concurrent policy')$$,'LISTING_LIMIT_REVISION_CONFLICT','limit policy has compare-and-swap');
reset role;select pg_temp.pro_user(1);set local role authenticated;
insert into pro_ids values('key',gen_random_uuid());
insert into pro_ids values('pro',(public.create_professional_listing('professional',(select v from pro_ids where k='key'))->>'listingId')::uuid);
select is(public.create_professional_listing('professional',(select v from pro_ids where k='key'))->>'listingId',(select v::text from pro_ids where k='pro'),'retry retains exact resource identity');
select throws_ok($$select public.create_professional_listing('space',(select v from pro_ids where k='key'))$$,'LISTING_CREATION_KEY_CONFLICT','same key cannot change kind');
insert into pro_ids values('a',(public.create_professional_listing('space',gen_random_uuid())->>'listingId')::uuid);
insert into pro_ids values('b',(public.create_professional_listing('space',gen_random_uuid())->>'listingId')::uuid);
select is(jsonb_array_length(public.list_my_professional_listings()->'items'),3,'same owner manages professional and two establishments');
select is(jsonb_array_length(public.list_my_professional_listings('space')->'items'),2,'kind filter works in PostgreSQL');
select is(jsonb_array_length(public.list_my_professional_listings(null,null,1)->'items'),1,'summary page is bounded');
select ok(public.list_my_professional_listings(null,null,1)->>'nextCursor' is not null,'summary exposes seek cursor');
select throws_ok($$select public.create_professional_listing('space',gen_random_uuid())$$,'LISTING_LIMIT_REACHED','configured type limit is enforced');
select is((public.get_my_professional_listing((select v from pro_ids where k='a'))->>'id'),(select v::text from pro_ids where k='a'),'getter identifies exact selected resource');
select public.save_professional_listing_draft((select v from pro_ids where k='pro'),pg_temp.pro_data('professional','Multi professional'),0);
select public.save_professional_listing_draft((select v from pro_ids where k='a'),pg_temp.pro_data('space','Multi establishment A'),0);
select public.save_professional_listing_draft((select v from pro_ids where k='b'),pg_temp.pro_data('space','Multi establishment B'),0);
select public.set_professional_listing_editorial((select v from pro_ids where k='pro'),1,'submitted');
select public.set_professional_listing_editorial((select v from pro_ids where k='a'),1,'submitted');
select public.set_professional_listing_editorial((select v from pro_ids where k='b'),1,'submitted');
reset role;select pg_temp.pro_admin();set local role authenticated;
select public.set_professional_listing_editorial((select v from pro_ids where k='pro'),2,'approved','Synthetic multi approval');
select public.set_professional_listing_editorial((select v from pro_ids where k='a'),2,'approved','Synthetic multi approval');
select public.set_professional_listing_editorial((select v from pro_ids where k='b'),2,'approved','Synthetic multi approval');
reset role;select pg_temp.pro_user(1);set local role authenticated;
insert into pro_ids values('order-pro',(public.quote_commercial_order((select v from pro_ids where k='pro'),'1',gen_random_uuid())->>'id')::uuid);
select public.confirm_commercial_order((select v from pro_ids where k='order-pro'),true);
insert into pro_ids values('order-a',(public.quote_commercial_order((select v from pro_ids where k='a'),'2',gen_random_uuid())->>'id')::uuid);
select public.confirm_commercial_order((select v from pro_ids where k='order-a'),true);
select public.confirm_commercial_order((select v from pro_ids where k='order-a'),true);
reset role;
select is((select cash_balance from public.wallets where user_id='75000000-0000-0000-0000-000000000001'),79,'two resources debit separately and replay does not debit twice');
select is(public.public_get_professional((select v from pro_ids where k='pro'))->>'displayName','Multi professional','paid professional remains public');
select is(public.public_get_professional((select v from pro_ids where k='a'))->>'displayName','Multi establishment A','only paid establishment A is public');
select is(public.public_get_professional((select v from pro_ids where k='b')),null::jsonb,'same owner contract never publishes unpaid establishment B');
select is((select count(*)::int from public.visibility_entitlements where resource_id in(select v from pro_ids where k in('pro','a','b'))),2,'entitlement is per resource, not per owner');
insert into public.storefront_media(id,storefront_id,storage_path,state,width,height,byte_size)select '75100000-0000-0000-0000-000000000051',v,v||'/75100000-0000-0000-0000-000000000051.webp','ready',32,32,100 from pro_ids where k='a';
select pg_temp.pro_user(1);set local role authenticated;
select throws_ok($$select public.save_professional_listing_draft((select v from pro_ids where k='b'),pg_temp.pro_data('space','Stolen same owner image','75100000-0000-0000-0000-000000000051'),3)$$,'INVALID_STOREFRONT_MEDIA','media cannot cross resources even with the same owner');
select public.save_professional_listing_draft((select v from pro_ids where k='a'),pg_temp.pro_data('space','PRIVATE CHANGE A'),3);
select is(public.public_get_professional((select v from pro_ids where k='a'))->>'displayName','Multi establishment A','edit preserves approved paid version A');
select is(public.get_my_professional_listing((select v from pro_ids where k='b'))->'draft'->>'displayName','Multi establishment B','editing A does not modify B');
reset role;
update public.visibility_entitlements set starts_at=clock_timestamp()-interval '2 days',expires_at=clock_timestamp()-interval '1 second' where resource_id=(select v from pro_ids where k='a');
select is(public.public_get_professional((select v from pro_ids where k='a')),null::jsonb,'expiration is independent for A');
select ok(public.public_get_professional((select v from pro_ids where k='pro')) is not null,'A expiration does not expire professional');
select pg_temp.pro_user(2);set local role authenticated;
select throws_ok($$select public.get_my_professional_listing((select v from pro_ids where k='a'))$$,'LISTING_NOT_FOUND','another owner cannot retrieve selected draft');
select is(jsonb_array_length(public.list_my_professional_listings()->'items'),0,'another owner sees no rows');
select throws_ok($$select public.quote_commercial_order((select v from pro_ids where k='b'),'1',gen_random_uuid())$$,'RESOURCE_NOT_ELIGIBLE','another owner cannot buy an entitlement for B');
reset role;select pg_temp.pro_admin();set local role authenticated;
select is((select count(*)::int from jsonb_array_elements(public.admin_accounts_snapshot()->'accounts')a where a->>'id'='75000000-0000-0000-0000-000000000001'),1,'account snapshot keeps one row for a multi-resource owner');
select is((select a->>'showcase_count' from jsonb_array_elements(public.admin_accounts_snapshot()->'accounts')a where a->>'id'='75000000-0000-0000-0000-000000000001'),'3','administrative account summary counts every concrete resource');
select public.admin_set_professional_listing_limit('space',0,1,'Pause only new establishment creations');
reset role;select pg_temp.pro_user(1);set local role authenticated;
select lives_ok($$select public.get_my_professional_listing((select v from pro_ids where k='a'))$$,'pause in creation preserves management');
insert into pro_ids values('renew',(public.quote_commercial_order((select v from pro_ids where k='a'),'1',gen_random_uuid())->>'id')::uuid);
select public.confirm_commercial_order((select v from pro_ids where k='renew'),true);
reset role;
select is((select expires_at-starts_at from public.visibility_entitlements where resource_id=(select v from pro_ids where k='a')),interval '24 hours','renewal targets only expired A despite pending review and paused creation');
select is(public.public_get_professional((select v from pro_ids where k='b')),null::jsonb,'renewal A still cannot activate B');
select is((select count(*)::int from public.economy_transactions where user_id='75000000-0000-0000-0000-000000000001' and natural_key in(select 'commercial:'||v::text from pro_ids where k in('order-pro','order-a','renew'))),3,'exactly one ledger debit per fulfilled order');
select pg_temp.set_test_user(null,true);set local role anon;
select throws_ok($$select public.list_my_professional_listings()$$,'42501',null,'anonymous users cannot enumerate owner central');
select throws_ok($$select * from public.professional_listing_limits$$,'42501',null,'configuration table is not directly public');
reset role;
select * from finish();rollback;
